//! F-037 V2: `apply_offline_viewer` output trees must equal the Python ones in
//! `fixtures/viewer_inject.json` (generated by `fixtures/make_viewer_inject.py`).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::collapsible_if)]
use cyoa_engine::offline_viewer::{ApplyOptions, AssetFetcher, FetchedAsset, apply_offline_viewer};
use serde_json::Value;
use std::{
    cell::RefCell,
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
};

fn b64(s: &str) -> Vec<u8> {
    let val = |c: u8| -> u32 {
        match c {
            b'A'..=b'Z' => u32::from(c - b'A'),
            b'a'..=b'z' => u32::from(c - b'a') + 26,
            b'0'..=b'9' => u32::from(c - b'0') + 52,
            b'+' => 62,
            b'/' => 63,
            _ => panic!("bad base64"),
        }
    };
    let bytes: Vec<u8> = s.bytes().filter(|c| *c != b'=').collect();
    let mut out = Vec::new();
    for chunk in bytes.chunks(4) {
        let mut n = 0_u32;
        for (i, c) in chunk.iter().enumerate() {
            n |= val(*c) << (18 - 6 * i);
        }
        let take = chunk.len() - 1;
        for i in 0..take {
            out.push((n >> (16 - 8 * i)) as u8);
        }
    }
    out
}

struct Fake {
    web: BTreeMap<String, (u16, String, Vec<u8>)>,
    requested: RefCell<Vec<String>>,
}
impl AssetFetcher for Fake {
    fn fetch(&self, url: &str) -> Option<FetchedAsset> {
        self.requested.borrow_mut().push(url.to_owned());
        self.web.get(url).map(|(s, c, b)| FetchedAsset {
            status: *s,
            content_type: c.clone(),
            body: b.clone(),
            too_large: false,
        })
    }
}

fn tree(root: &Path) -> BTreeMap<String, Vec<u8>> {
    let mut out = BTreeMap::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(d) = stack.pop() {
        for e in fs::read_dir(&d).unwrap() {
            let p = e.unwrap().path();
            if p.is_dir() {
                stack.push(p);
            } else {
                let rel = p
                    .strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                out.insert(rel, fs::read(&p).unwrap());
            }
        }
    }
    out
}

/// Report files carry a local timestamp line; blank it on both sides.
fn normalise(path: &str, bytes: &[u8]) -> Vec<u8> {
    if !path.ends_with(".txt") {
        return bytes.to_vec();
    }
    String::from_utf8_lossy(bytes)
        .replace("\r\n", "\n")
        .split_inclusive('\n')
        .map(|l| {
            if l.starts_with("Generated : ") {
                "Generated : <ts>\n".to_owned()
            } else {
                l.to_owned()
            }
        })
        .collect::<String>()
        .into_bytes()
}

#[test]
fn apply_offline_viewer_matches_python_trees() {
    let f: Value = serde_json::from_str(
        &fs::read_to_string(
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/viewer_inject.json"),
        )
        .unwrap(),
    )
    .unwrap();
    let tmp = tempfile::tempdir().unwrap();
    let viewers = tmp.path().join("viewers");
    fs::create_dir_all(&viewers).unwrap();
    for (name, data) in f["viewers"].as_object().unwrap() {
        fs::write(viewers.join(name), b64(data.as_str().unwrap())).unwrap();
    }
    let web: BTreeMap<String, (u16, String, Vec<u8>)> = f["fake_web"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(u, v)| {
            (
                u.clone(),
                (
                    v[0].as_u64().unwrap() as u16,
                    v[1].as_str().unwrap().to_owned(),
                    b64(v[2].as_str().unwrap()),
                ),
            )
        })
        .collect();

    let mut failures = Vec::new();
    for case in f["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let out = tmp.path().join(format!("out_{id}"));
        fs::create_dir_all(&out).unwrap();
        for d in case["pre_existing"].as_array().unwrap() {
            fs::create_dir_all(out.join(d.as_str().unwrap())).unwrap();
        }
        let mut asset_dirs: Vec<(String, PathBuf)> = Vec::new();
        for (kind, files) in case["assets"].as_object().unwrap() {
            let src = tmp.path().join(format!("assets_{id}_{kind}"));
            for (rel, data) in files.as_object().unwrap() {
                let p = src.join(rel);
                fs::create_dir_all(p.parent().unwrap()).unwrap();
                fs::write(p, b64(data.as_str().unwrap())).unwrap();
            }
            asset_dirs.push((kind.clone(), src));
        }
        let cache_files = case["cache_dir_files"].as_object().unwrap();
        let cache = tmp.path().join(format!("cache_{id}"));
        for (rel, data) in cache_files {
            let p = cache.join(rel);
            fs::create_dir_all(p.parent().unwrap()).unwrap();
            fs::write(p, b64(data.as_str().unwrap())).unwrap();
        }
        let fake = Fake {
            web: web.clone(),
            requested: RefCell::new(Vec::new()),
        };
        let meta = case["meta"].as_object().unwrap().clone();
        let res = apply_offline_viewer(ApplyOptions {
            viewers_dir: &viewers,
            output_dir: &out,
            project_json_str: case["project_text"].as_str().unwrap(),
            viewer_meta: &meta,
            file_name: case["file_name"].as_str().unwrap(),
            asset_source_dirs: if asset_dirs.is_empty() {
                None
            } else {
                Some(&asset_dirs)
            },
            source_html: case["source_html"].as_str().unwrap_or(""),
            source_url: case["source_url"].as_str().unwrap(),
            preserved_asset_cache_dir: if cache_files.is_empty() {
                None
            } else {
                Some(&cache)
            },
            fetcher: &fake,
            allow_internal: false,
            cheat_panel: true,
        });
        let got_res = res.map(|p| {
            p.strip_prefix(&out)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/")
        });
        if got_res.as_deref() != case["result"].as_str() {
            failures.push(format!("{id}: result {got_res:?} != {}", case["result"]));
        }
        let want_req: Vec<String> = case["requested"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect();
        if *fake.requested.borrow() != want_req {
            failures.push(format!(
                "{id}: requested\n  rust {:?}\n  py   {want_req:?}",
                fake.requested.borrow()
            ));
        }
        let got = tree(&out);
        let want: BTreeMap<String, Vec<u8>> = case["tree"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| {
                let bytes = match v.get("text") {
                    Some(t) => t.as_str().unwrap().as_bytes().to_vec(),
                    None => b64(v["b64"].as_str().unwrap()),
                };
                (k.clone(), bytes)
            })
            .collect();
        let gk: Vec<_> = got.keys().collect();
        let wk: Vec<_> = want.keys().collect();
        if gk != wk {
            failures.push(format!("{id}: files\n  rust {gk:?}\n  py   {wk:?}"));
        }
        for (k, w) in &want {
            if let Some(g) = got.get(k) {
                if normalise(k, g) != normalise(k, w) {
                    failures.push(format!(
                        "{id}: {k} differs\n  rust {:?}\n  py   {:?}",
                        String::from_utf8_lossy(g),
                        String::from_utf8_lossy(w)
                    ));
                }
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
